-- 收付款核销真实种子数据（batch 132）
-- 背景：finance_write_off 长期 0 行，核销接口只写流水不回写余额（P1-6 缺陷）
-- 本迁移：建真实关联发票 + 核销流水，并同步回写 fin_receivable/fin_payable 的已收/已付/余额/状态
-- 幂等：先备份再按前缀清理后重建

CREATE TABLE IF NOT EXISTS finance_write_off_bak_20260926 AS SELECT * FROM finance_write_off;
CREATE TABLE IF NOT EXISTS finance_invoice_bak_20260926 AS SELECT * FROM finance_invoice;

DELETE FROM finance_write_off WHERE invoice_no LIKE 'SI20260926%' OR invoice_no LIKE 'PI20260926%';
DELETE FROM finance_invoice_item WHERE invoice_id IN (SELECT id FROM finance_invoice WHERE invoice_no LIKE 'SI20260926%' OR invoice_no LIKE 'PI20260926%');
DELETE FROM finance_invoice WHERE invoice_no LIKE 'SI20260926%' OR invoice_no LIKE 'PI20260926%';

-- 销售发票（关联 12 张应收单）：前 8 张全额核销，后 4 张核销 50%

-- 采购发票（关联 12 张应付单）：前 8 张全额核销，后 4 张核销 50%

